<script>
const products=@json($products), active=products.filter(p=>p.active);
const message=document.getElementById('message');
function notify(s){message.textContent=s;message.style.display='block';}
async function api(path,method,data){const r=await fetch('/api/v1'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify(data)});const json=await r.json();if(!r.ok)throw Error(json.errors?Object.values(json.errors).flat().join('\n'):json.message);return json;}
function money(c){return 'S/ '+(c/100).toFixed(2);}
function estimate(){let sum=0;document.querySelectorAll('.line').forEach(l=>{const p=active.find(p=>p.id==l.querySelector('select').value);sum+=(p?.price_cents||0)*Number(l.querySelector('input').value);});document.getElementById('estimate').textContent=money(sum);}
function addLine(){if(!active.length){notify('Primero registra un producto activo.');return;}const l=document.createElement('div');l.className='line';const s=document.createElement('select');s.setAttribute('aria-label','Producto');active.forEach(p=>{const o=document.createElement('option');o.value=p.id;o.textContent=p.name+' · '+money(p.price_cents);s.append(o);});const q=document.createElement('input');q.type='number';q.min=1;q.max=100;q.value=1;q.required=true;q.setAttribute('aria-label','Cantidad');const b=document.createElement('button');b.type='button';b.textContent='×';b.setAttribute('aria-label','Quitar producto');b.onclick=()=>{l.remove();estimate();};l.append(s,q,b);l.oninput=estimate;document.getElementById('lines').append(l);estimate();}
document.getElementById('addLine').onclick=addLine;addLine();
document.getElementById('editProduct').onchange=e=>{const p=products.find(p=>p.id==e.target.value);document.getElementById('productName').value=p?.name||'';document.getElementById('productPrice').value=p?p.price_cents/100:'';document.getElementById('productActive').value=p&&!p.active?'0':'1';};
document.getElementById('productForm').onsubmit=async e=>{e.preventDefault();const id=document.getElementById('editProduct').value;try{await api('/products'+(id?'/'+id:''),id?'PUT':'POST',{name:document.getElementById('productName').value,price_cents:Math.round(Number(document.getElementById('productPrice').value)*100),active:document.getElementById('productActive').value==='1'});location.reload();}catch(err){notify(err.message);}};
let pending=null;
const uuid=()=> '10000000-1000-4000-8000-100000000000'.replace(/[018]/g,c=>(Number(c)^crypto.getRandomValues(new Uint8Array(1))[0]&15>>Number(c)/4).toString(16));
document.getElementById('orderForm').onsubmit=async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));const grouped={};document.querySelectorAll('.line').forEach(l=>{const id=Number(l.querySelector('select').value);grouped[id]=(grouped[id]||0)+Number(l.querySelector('input').value);});d.items=Object.entries(grouped).map(([id,q])=>({product_id:Number(id),quantity:q}));const signature=JSON.stringify(d);if(!pending||pending.signature!==signature)pending={signature,id:uuid()};d.client_request_id=pending.id;const b=document.getElementById('submitOrder');b.disabled=true;try{await api('/orders','POST',d);location.reload();}catch(err){notify(err.message);}finally{b.disabled=false;}};
document.querySelectorAll('[data-order]').forEach(s=>s.onchange=async()=>{s.disabled=true;try{await api('/orders/'+s.dataset.order+'/status','PATCH',{status:s.value});location.reload();}catch(err){notify(err.message);s.disabled=false;}});
</script>@endsection
